mapper.select:
select *
from lab_reservation
where 1 = 1

    and reservation_no like concat('%', #{reservationNo}, '%')


    and lab_id = #{labId}


    and applicant_user_id = #{applicantUserId}


    and approver_user_id = #{approverUserId}


    and status = #{status}


    and reservation_date = #{reservationDate}

order by id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_reservation
where 1 = 1

    and reservation_no like concat('%', #{reservationNo}, '%')


    and lab_id = #{labId}


    and applicant_user_id = #{applicantUserId}


    and approver_user_id = #{approverUserId}


    and status = #{status}


    and reservation_date = #{reservationDate}

select *
from lab_reservation
where applicant_user_id = #{userId}
order by id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_reservation
where applicant_user_id = #{userId}

mapper.update:
update lab_reservation
set approver_user_id = #{approverUserId},
        status = #{status},
        reject_reason = #{rejectReason}
where id = #{id}

update lab_reservation
set status = 4
where id = #{id}

update lab_reservation
set check_in_time = now()
where id = #{id}

mapper.select:
select count(*)
from lab_reservation
where lab_id = #{labId}
    and status in (1, 2, 5)
    and start_time < #{endTime}
    and end_time > #{startTime}

select *
from lab_reservation
where lab_id = #{labId}
    and status in (1, 2, 5)
    and reservation_date = #{reservationDate}
order by start_time asc

select reservation_type as name, count(*) as count
from lab_reservation
where 1 = 1

    and reservation_date  >=  #{startDate}


    and reservation_date  <=  #{endDate}


    and lab_id = #{labId}

group by reservation_type

select status as name, count(*) as count
from lab_reservation
where 1 = 1

    and reservation_date  >=  #{startDate}


    and reservation_date  <=  #{endDate}


    and lab_id = #{labId}

group by status

select l.lab_name as name, count(r.id) as count from lab l left join lab_reservation r on l.id = r.lab_id where l.deleted = 0
and l.department_id = #{departmentId}
and l.id = #{labId}
and (r.id is null or r.reservation_date >= #{startDate})
and (r.id is null or r.reservation_date <= #{endDate})
group by l.id, l.lab_name order by count desc, l.id asc

select date_format(start_time, '%H:00') as name, count(*) as count
from lab_reservation
where 1 = 1

    and reservation_date  >=  #{startDate}


    and reservation_date  <=  #{endDate}


    and lab_id = #{labId}

group by date_format(start_time, '%H:00')
order by name asc

select date_format(reservation_date, '%Y-%m-%d') as name, count(*) as count from lab_reservation where 1 = 1
and reservation_date >= #{startDate}
and reservation_date <= #{endDate}
group by reservation_date order by reservation_date asc
